-- paperclip:migration-safety-ignore large-create-index-not-concurrently: Drizzle migrations are transactional, so CONCURRENTLY is unavailable. Production activity_log holds about 16k rows; the build measured 25 ms on a production copy.
CREATE INDEX "activity_log_company_entity_run_idx" ON "activity_log" USING btree ("company_id","entity_type","entity_id","run_id");--> statement-breakpoint
-- paperclip:migration-safety-ignore large-create-index-not-concurrently: Drizzle migrations are transactional, so CONCURRENTLY is unavailable. The partial predicate matches a handful of rows; the build measured 13 ms over 84k production events.
CREATE INDEX "heartbeat_run_events_retry_exhausted_run_idx" ON "heartbeat_run_events" USING btree ("run_id","id") WHERE "heartbeat_run_events"."event_type" = 'lifecycle' and "heartbeat_run_events"."message" like 'Bounded retry exhausted%';--> statement-breakpoint
-- paperclip:migration-safety-ignore large-create-index-not-concurrently: Drizzle migrations are transactional, so CONCURRENTLY is unavailable. The partial predicate matches only runs that registered secrets; the build measured 190 ms over 1.8k production runs.
CREATE INDEX "heartbeat_runs_company_ctx_issue_redaction_idx" ON "heartbeat_runs" USING btree ("company_id",("context_snapshot" ->> 'issueId')) WHERE "heartbeat_runs"."context_snapshot" ? 'paperclipSecretRedactions';